    parser=argparse.ArgumentParser(); parser.add_argument("--output-dir",type=Path,default=repo_root()/"experiment-results/phase58_pd_shape_aware_iterative_refinement"); args=parser.parse_args(); print(json.dumps(verify(args.output_dir.resolve()),ensure_ascii=False,indent=2))
